const now = new Date().toISOString();
return [
  { json: { client_id: 'demo', source: 'reddit', content_id: 'reddit-001', url: 'https://example.com/reddit-001', author: 'sample_user', text: 'Looking for greenhouse automation and crop monitoring options in Canada.', created_at: now, keywords: ['greenhouse', 'automation'], territory: 'Canada' } },
  { json: { client_id: 'demo', source: 'youtube', content_id: 'youtube-001', url: 'https://example.com/youtube-001', author: 'sample_channel', text: 'Question: what is the best way to monitor irrigation and sensors remotely?', created_at: now, keywords: ['monitoring', 'irrigation'], territory: 'Canada' } },
  { json: { client_id: 'demo', source: 'news', content_id: 'news-001', url: 'https://example.com/news-001', author: 'sample_news', text: 'Regional producer announces expansion of controlled environment agriculture facility.', created_at: now, keywords: ['expansion', 'controlled environment'], territory: 'Canada' } }
];

const seen = new Set();
const allowedTerritories = ['Canada', 'USA', 'United States'];
const blockedTerms = ['giveaway', 'coupon spam', 'crypto'];
return $input.all()
  .filter(item => {
    const j = item.json;
    const key = `${j.source}:${j.content_id}`;
    if (seen.has(key)) return false;
    seen.add(key);
    if (!j.text || j.text.length < 40) return false;
    if (!allowedTerritories.includes(j.territory)) return false;
    const lower = j.text.toLowerCase();
    if (blockedTerms.some(term => lower.includes(term))) return false;
    return true;
  })
  .map(item => ({ json: { ...item.json, filter_status: 'PASSED', filtered_at: new Date().toISOString() } }));

function scoreSignal(text) {
  const lower = text.toLowerCase();
  let score = 30;
  if (lower.includes('looking for') || lower.includes('best way') || lower.includes('recommend')) score += 25;
  if (lower.includes('automation') || lower.includes('monitor') || lower.includes('sensor')) score += 20;
  if (lower.includes('expansion') || lower.includes('facility')) score += 15;
  if (lower.includes('urgent') || lower.includes('asap')) score += 10;
  return Math.min(score, 100);
}
return $input.all().map(item => {
  const score = scoreSignal(item.json.text || '');
  const urgency = score >= 75 ? 'high' : score >= 55 ? 'medium' : 'low';
  const recommendation = score >= 70 ? 'research_and_draft' : score >= 50 ? 'keep_for_review' : 'log_only';
  return { json: { ...item.json, agent: 'Analyst', score, urgency, recommendation, analysis_summary: `Potential ${urgency} commercial signal from ${item.json.source}.` } };
});

return $input.all().map(item => {
  const j = item.json;
  const action = j.score >= 70 ? 'Prepare a human-approved outreach draft.' : 'Add to daily digest for review.';
  const draft = j.score >= 70
    ? `Bonjour, j'ai vu votre question au sujet de ${j.keywords?.join(', ') || 'l\'automatisation'}. Nous travaillons sur des solutions de veille et d'automatisation pour aider les equipes a evaluer ce type de besoin. Si vous voulez, je peux vous partager une piste simple a comparer.`
    : '';
  return { json: { ...j, agent: 'Writer', proposed_action: action, draft_message: draft } };
});

return $input.all().map(item => {
  const j = item.json;
  const text = `${j.text || ''} ${j.draft_message || ''}`.toLowerCase();
  const risky = ['guarantee', 'secret', 'password', 'medical advice', 'legal advice'].some(term => text.includes(term));
  let approval_status = 'VALIDATION_HUMAINE_OBLIGATOIRE';
  if (risky) approval_status = 'BLOQUE';
  if (j.score < 50) approval_status = 'APPROUVE_LOG_ONLY';
  return { json: { ...j, agent: 'Guardian', approval_status, guardian_notes: risky ? 'Risk term detected. Human admin review required.' : 'No blocking risk detected. Human approval still required for public outreach.' } };
});

return $input.all().map(item => ({
  json: {
    level: item.json.approval_status === 'BLOQUE' ? 'WARNING' : 'INFO',
    client_id: item.json.client_id,
    workflow_name: 'HERMES - MAIN PIPELINE',
    agent: item.json.agent,
    source: item.json.source,
    content_id: item.json.content_id,
    action: item.json.proposed_action,
    score: item.json.score,
    approval_status: item.json.approval_status,
    metadata: item.json
  }
}));
